#!/usr/bin/env node
var FS=require("fs"),JSON5=require("./json5"),Path=require("path"),USAGE=["Usage: json5 -c path/to/file.json5 ...","Compiles JSON5 files into sibling JSON files with the same basenames."].join("\n"),args=process.argv;(args.length<4||"-c"!==args[2])&&(console.error(USAGE),process.exit(1));var cwd=process.cwd(),files=args.slice(3);files.forEach(function(e){var s=Path.resolve(cwd,e),r=Path.basename(s,".json5"),a=Path.dirname(s),i=FS.readFileSync(s,"utf8"),n=JSON5.parse(i),o=JSON.stringify(n,null,4);s=Path.join(a,r+".json"),FS.writeFileSync(s,o,"utf8")});